/* prog28_levenshtein – re‑implementation of the original binary
 *
 * Behaviour:
 *   prog28_levenshtein <string1> <string2>
 *
 *   * If the number of arguments is not 3 → prints "USAGE\n"
 *   * If either string is longer than 64 characters → prints "TOO_LONG\n"
 *   * Otherwise prints the Levenshtein distance between the two strings
 *     followed by a newline.
 *
 * The algorithm is the classic O(|s|·|t|) DP solution.
 */

#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_LEN 64

int main(int argc, char *argv[])
{
    /* -----------------------------------------------------------------
       Argument handling
       ----------------------------------------------------------------- */
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }

    const char *s = argv[1];
    const char *t = argv[2];

    size_t len_s = strlen(s);
    size_t len_t = strlen(t);

    if (len_s > MAX_LEN || len_t > MAX_LEN) {
        puts("TOO_LONG");
        return 0;
    }

    /* -----------------------------------------------------------------
       DP table – we allocate (len_s+1)*(len_t+1) integers.
       The original binary used a static 65×65 array; allocating exactly
       what we need keeps the program simple while preserving the same
       results.
       ----------------------------------------------------------------- */
    int (*dp)[MAX_LEN + 1] = calloc((len_s + 1), sizeof *dp);
    if (!dp) {
        perror("calloc");
        return 1;
    }

    /* initialise first row and column */
    for (size_t i = 0; i <= len_s; ++i) dp[i][0] = (int)i;
    for (size_t j = 0; j <= len_t; ++j) dp[0][j] = (int)j;

    /* fill the table */
    for (size_t i = 1; i <= len_s; ++i) {
        for (size_t j = 1; j <= len_t; ++j) {
            int cost = (s[i - 1] == t[j - 1]) ? 0 : 1;

            int del  = dp[i - 1][j] + 1;          /* deletion */
            int ins  = dp[i][j - 1] + 1;          /* insertion */
            int subst = dp[i - 1][j - 1] + cost; /* substitution */

            int best = del;
            if (ins < best)  best = ins;
            if (subst < best) best = subst;

            dp[i][j] = best;
        }
    }

    printf("%d\n", dp[len_s][len_t]);

    free(dp);
    return 0;
}
